const starterSignature=rung=>Array.isArray(rung?.elements)&&rung.elements.length===3&&rung.elements[0].type==='contact'&&rung.elements[0].mode==='nc'&&rung.elements[0].tag==='Stop'&&rung.elements[1].type==='contact'&&rung.elements[1].mode==='no'&&rung.elements[1].tag==='Start'&&rung.elements[2].type==='coil'&&rung.elements[2].mode==='ote'&&rung.elements[2].tag==='Motor';
function isLegacySeedProject(project){const knownTags=new Set(['Start','Stop','Motor','InputA','Counter','Counter.ACC','Counter.PRE','Counter.Q']);const tagNames=Object.keys(project.tags||{}),inputTags=project.inputTags||[],monitorTags=project.monitorTags||[],extra=project.rungs[1]?.elements||[];const sameSet=(values,expected)=>values.length===expected.length&&expected.every(value=>values.includes(value));return project.rungs.length===2&&starterSignature(project.rungs[0])&&tagNames.every(tag=>knownTags.has(tag))&&['Start','Stop','Motor','InputA','Counter'].every(tag=>tagNames.includes(tag))&&sameSet(inputTags,['Start','Stop','InputA'])&&sameSet(monitorTags,['Start','Stop','Motor','InputA','Counter'])&&extra.length===2&&extra.some(item=>item.type==='contact'&&item.tag==='InputA')&&extra.some(item=>item.type==='counter'&&item.tag==='Counter');}
function repairComponentTags(project){project.tags??={};project.inputTags??=[];const elements=[];const walk=items=>{for(const item of items||[]){elements.push(item);if(item.type==='branch')for(const path of item.paths||[])walk(path);}};for(const rung of project.rungs)walk(rung.elements);const outputTags=new Set(elements.filter(item=>item.type==='coil').map(item=>item.tag).filter(Boolean));const generatedTags=new Set();for(const item of elements){if(item.type==='timer')for(const suffix of ['EN','TT','Q','ACC','ET','PRE'])generatedTags.add(`${item.tag}.${suffix}`);if(item.type==='counter')for(const suffix of ['Q','ACC','PRE'])generatedTags.add(`${item.tag}.${suffix}`);if((item.type==='compare'||item.type==='math')&&item.dest)generatedTags.add(item.dest);}let changed=false;for(const item of elements){const tag=item.type==='contact'?item.tag:item.type==='coil'?item.tag:item.type==='compare'||item.type==='math'?item.dest:null;if(!tag)continue;if(!Object.hasOwn(project.tags,tag)&&!generatedTags.has(tag)){project.tags[tag]=item.type==='math'?0:false;changed=true;}if(item.type==='contact'&&!outputTags.has(tag)&&!generatedTags.has(tag)&&!project.inputTags.includes(tag)){project.inputTags.push(tag);changed=true;}}return changed;}
export function loadProject(){try{const parsed=JSON.parse(localStorage.getItem('lltl-project-v1'));if(parsed&&typeof parsed==='object'&&Array.isArray(parsed.rungs)){if(isLegacySeedProject(parsed)){const migrated=clone(starter);localStorage.setItem('lltl-project-v1',JSON.stringify(migrated));return migrated;}parsed.tags??={};parsed.inputTags??=[];let changed=repairComponentTags(parsed);if(!Array.isArray(parsed.monitorTags)){parsed.monitorTags=['Start','Stop','Motor'].filter(tag=>Object.hasOwn(parsed.tags,tag));changed=true;}else{const valid=parsed.monitorTags.filter(tag=>Object.hasOwn(parsed.tags,tag));if(valid.length!==parsed.monitorTags.length){parsed.monitorTags=valid;changed=true;}}if(changed)localStorage.setItem('lltl-project-v1',JSON.stringify(parsed));return parsed;}}catch{}return clone(starter);}
function save(){localStorage.setItem('lltl-project-v1',JSON.stringify(circuit));}
function escape(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function setFeedback(text){feedback=text;const box=el('[data-feedback]');if(box){box.textContent=text;box.hidden=!text;}}
function recordScan(dt=simulationStepMs){const before=clone(last.tags);last=scan(circuit,memory,dt);memory=last.memory;scanNumber++;history.unshift({number:scanNumber,trace:last.trace.slice(-6),changed:Object.entries(last.tags).filter(([k,v])=>before[k]!==v).map(([k,v])=>`${k} → ${v===true?'ON':v===false?'OFF':v}`)});history=history.slice(0,12);}
function scanOnce(dt=simulationStepMs){recordScan(dt);updateSimulationView();}
function setTag(name,value,repaint=true){circuit.tags[name]=value;save();last=scan(circuit,memory,0);memory=last.memory;scanNumber++;if(repaint)render();else updateSimulationView();}
function reset(){running=false;for(const key of Object.keys(circuit.tags))circuit.tags[key]=typeof circuit.tags[key]==='number'?0:false;memory=emptyMemory();last=scan(circuit);history=[];scanNumber=0;save();render();setFeedback('Simulation state reset. Your circuit and tag assignments were kept.');}
function startRun(){if(running)return;running=true;render();}
let interval;setInterval(()=>{if(running){recordScan(simulationStepMs);updateSimulationView();}},100);

function navButton(name,icon,count=''){return `<button class="${activeTab===name?'active':''}" data-tab="${name}" ${activeTab===name?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span><span>${name}</span>${count?`<span class="nav-count">${count}</span>`:''}</button>`;}
function header(){return `<header class="topbar"><div class="brand" aria-label="Ladder Logic Tutor Lab"><span class="brand-mark"><span></span><span></span><span></span></span><span class="brand-copy"><b>LADDER LOGIC</b><small>TUTOR LAB</small></span></div><nav class="main-nav" aria-label="Main navigation">${navButton('Learn','▤','12')}${navButton('Playground','⌁')}${navButton('Components','▦')}${navButton('Challenges','◇')}</nav><div class="top-actions"><span class="saved-indicator"><span></span>Saved locally</span><button class="theme-switch" data-action="theme" aria-label="Switch to ${theme==='dark'?'light':'dark'} theme">${theme==='dark'?'☼ Light':'◐ Dark'}</button><button class="help-button" data-action="help" aria-label="About this application">? <span>About</span></button></div></header>`;}
function heading(eyebrow,title,subtitle,extra=''){return `<div class="section-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${extra}</div>`;}
