function rungWidth(rung){return Math.max(900,300+Math.max(0,rung.elements.length-1)*190);}
function ladderWidth(){return Math.max(900,...circuit.rungs.map(rungWidth));}
function clientToViewY(svg,clientY){const rect=svg.getBoundingClientRect(),view=svg.viewBox.baseVal;return(clientY-rect.top)*view.height/rect.height+view.y;}
function rungPositions(rung,width=rungWidth(rung)){const count=rung.elements.length;if(!count)return[];const left=150,right=width-100;if(count===1)return[rung.elements[0].type==='coil'?right:(left+right)/2];return rung.elements.map((_,i)=>left+i*(right-left)/(count-1));}
function componentX(rung,index){return rungPositions(rung,ladderWidth())[index]??150;}
function rungSvg(r,index){const width=ladderWidth(),positions=rungPositions(r,width),events=r.elements.map(e=>traceFor(r.id,e.id)),offset=index*180,isSelected=selectedRungId===r.id,half=e=>e.type==='branch'?62:30;let wires='';if(r.elements.length){wires+=wireMarkup(50,positions[0]-half(r.elements[0]),r.id,r.elements[0].id,'input',Boolean(events[0]?.inputPower));for(let i=0;i<r.elements.length;i++){const to=i===r.elements.length-1?width-50:positions[i+1]-half(r.elements[i+1]);wires+=wireMarkup(positions[i]+half(r.elements[i]),to,r.id,r.elements[i].id,'output',Boolean(events[i]?.outputPower));}}else wires=wireMarkup(50,width-50,r.id,r.id,'path',false);return `<g class="ladder-row${isSelected?' rung-selected':''}" data-rung="${escape(r.id)}" transform="translate(0 ${offset})"><line x1="50" y1="22" x2="50" y2="158" class="rail-hit-segment" data-select-rung="${escape(r.id)}" data-rung-rail="${escape(r.id)}" aria-label="Select rung left rail"/><line x1="${width-50}" y1="22" x2="${width-50}" y2="158" class="rail-hit-segment" data-select-rung="${escape(r.id)}" data-rung-rail="${escape(r.id)}" aria-label="Select rung right rail"/><line x1="50" y1="90" x2="${width-50}" y2="90" class="rail-highlight"/><text x="11" y="52" class="rung-number">${String(index+1).padStart(2,'0')}</text><g class="rung-drag-handle" data-rung-handle="${escape(r.id)}" role="button" tabindex="0" aria-label="Drag rung ${index+1} to reorder" transform="translate(12 72)"><rect x="0" y="0" width="26" height="32" rx="5"/><text x="13" y="21" text-anchor="middle">⠿</text></g>${wires}<line x1="60" y1="35" x2="60" y2="145" class="insertion-indicator" visibility="hidden" data-insertion-indicator="${escape(r.id)}"/>${r.elements.map((e,i)=>symbol(e,i,r.id)).join('')}</g>`;}
function ladderWorkspace(){const width=ladderWidth(),height=Math.max(180,circuit.rungs.length*180);return `<div class="ladder-workspace" data-ladder-workspace><svg class="ladder-svg" data-workspace-svg viewBox="0 0 ${width} ${height}" width="${width}" height="${height}" role="group" aria-label="Ladder workspace with ${circuit.rungs.length} rungs"><line x1="50" y1="22" x2="50" y2="${height-22}" class="rail-line shared-rail" aria-label="Left rail"/><line x1="${width-50}" y1="22" x2="${width-50}" y2="${height-22}" class="rail-line shared-rail" aria-label="Right rail"/>${circuit.rungs.map(rungSvg).join('')}</svg></div>`;}
function branchPathCenters(path){return path.map((_,index)=>-48+(index+1)*(96/(path.length+1)));}
function branchMarkup(branch,rungId,parentX){
 const paths=branch.paths.map((path,pathIndex)=>{
  const y=pathIndex===0?-29:29,centers=branchPathCenters(path),branchPath=`${branch.id}.${pathIndex}`;
  let contents='';
  if(!path.length)contents=`<line x1="-58" y1="${y}" x2="58" y2="${y}" class="branch-wire"/><text x="0" y="${y-12}" text-anchor="middle" class="branch-drop-label" pointer-events="none">Drop contact here</text>`;
  else{
   let from=-58;
   for(let index=0;index<path.length;index++){
    const child=path[index],x=centers[index],traceId=`${branchPath}/${child.id}`,state=traceFor(rungId,traceId),condition=state?.condition,active=Boolean(state?.outputPower);
    const to=x-10;contents+=wireMarkup(from,to,rungId,traceId,'input',Boolean(state?.inputPower)).replaceAll('y1="90"',`y1="${y}"`).replaceAll('y2="90"',`y2="${y}"`);
    const shape=child.type==='contact'?`<line x1="-4" y1="-8" x2="-4" y2="8" class="contact-line"/><line x1="4" y1="-8" x2="4" y2="8" class="contact-line"/>${child.mode==='nc'?'<line x1="-9" y1="8" x2="9" y2="-8" class="contact-line"/>':''}`:`<rect x="-8" y="-9" width="16" height="18" class="branch-block"/>`;
    contents+=`<g class="branch-instruction ${active?'active':''}${condition===true?' condition-true':condition===false?' condition-false':''}${selectedComponentId===child.id?' selected-symbol':''}" transform="translate(${x} ${y})" data-sim-symbol data-select="${escape(child.id)}" data-element-id="${escape(child.id)}" data-rung-id="${escape(rungId)}" data-trace-id="${escape(traceId)}" data-element-type="${escape(child.type)}" data-output-tag="${escape(child.tag||'')}" data-drag-element="${escape(child.id)}" data-drag-rung="${escape(rungId)}" data-drag-branch="${escape(branch.id)}" data-drag-path="${pathIndex}" data-branch-x="${parentX}" role="button" tabindex="0" aria-label="Select ${escape(child.type)} ${escape(child.tag||'')}"><rect x="-15" y="-17" width="30" height="34" rx="4" class="component-hitbox" fill="#000" fill-opacity="0.001" pointer-events="all" aria-hidden="true"/>${shape}<title data-trace-detail>${escape(state?.detail||child.type)}</title></g><text x="${x}" y="${y-12}" text-anchor="middle" class="tag-label branch-tag">${escape(child.tag||child.type)}</text>`;
    from=x+10;
   }
   const lastId=`${branchPath}/${path.at(-1).id}`;contents+=wireMarkup(from,58,rungId,lastId,'output',Boolean(traceFor(rungId,lastId)?.outputPower)).replaceAll('y1="90"',`y1="${y}"`).replaceAll('y2="90"',`y2="${y}"`);
  }
  return `<g class="branch-path" data-branch-drop="${escape(branch.id)}" data-path-index="${pathIndex}" data-branch-x="${parentX}" data-rung="${escape(rungId)}"><rect x="-60" y="${y-19}" width="120" height="38" rx="4" class="branch-drop-zone" aria-label="Drop an instruction in branch path ${pathIndex+1}"/><line x1="-58" y1="${y}" x2="58" y2="${y}" class="branch-path-hit" data-select-rung="${escape(rungId)}" aria-label="Select rung branch wire"/>${contents}<line x1="0" y1="${y-17}" x2="0" y2="${y+17}" class="branch-insertion-indicator" data-branch-insertion="${escape(branch.id)}-${pathIndex}" visibility="hidden" pointer-events="none"/></g>`;
 }).join('');
 return `<line x1="-58" y1="-29" x2="-58" y2="29" class="branch-wire"/><line x1="58" y1="-29" x2="58" y2="29" class="branch-wire"/>${paths}<text x="0" y="4" text-anchor="middle" class="symbol-label branch-or-label">OR</text>`;
}
function clientToViewX(row,clientX){const svg=row.querySelector('svg')||row.closest('svg'),rect=svg.getBoundingClientRect(),view=svg.viewBox.baseVal;return(clientX-rect.left)*view.width/rect.width+view.x;}
function rungDropIndex(row,clientX,allowAfterCoil=true){const x=clientToViewX(row,clientX),rung=circuit.rungs.find(item=>item.id===row.dataset.rung),positions=rungPositions(rung,ladderWidth()),limit=positions.length;if(!limit)return 0;const boundaries=[(35+positions[0])/2,...positions.slice(1).map((position,i)=>(positions[i]+position)/2),(positions.at(-1)+(ladderWidth()-50))/2];let index=boundaries.findIndex(boundary=>x<boundary);if(index<0)index=limit;if(!allowAfterCoil&&rung.elements.at(-1)?.type==='coil')index=Math.min(index,limit-1);return Math.max(0,index);}
function branchDropIndex(row,branchId,pathIndex,parentX,clientX){const branch=findElement(branchId),path=branch?.paths[pathIndex]||[],x=clientToViewX(row,clientX)-parentX,centers=branchPathCenters(path),bounds=[-58,...centers,58];let index=bounds.findIndex(boundary=>x<(bounds[boundary===-58?0:0]));index=bounds.slice(1).findIndex(boundary=>x<boundary);return index<0?path.length:index;}
function branchPathInsertX(path,index){const centers=branchPathCenters(path),bounds=[-58,...centers,58];return(bounds[index]+bounds[index+1])/2;}
function showDropIndicator(row,clientX){clearDropIndicators(row);const index=rungDropIndex(row,clientX,!paletteDrag),line=row.querySelector('[data-insertion-indicator]')||row.closest('svg')?.querySelector(`[data-insertion-indicator="${row.dataset.rung}"]`),svg=row.querySelector('svg')||row.closest('svg'),width=svg.viewBox.baseVal.width,rung=circuit.rungs.find(item=>item.id===row.dataset.rung),positions=rungPositions(rung,width),x=index===0?(35+(positions[0]??width-30))/2:index>=positions.length?((positions.at(-1)??35)+(width-30))/2:(positions[index-1]+positions[index])/2;row.classList.add('drop-target');row.dataset.dropIndex=String(index);line?.setAttribute('x1',x);line?.setAttribute('x2',x);line?.setAttribute('y1',35);line?.setAttribute('y2',145);line?.setAttribute('visibility','visible');}
function showBranchDropIndicator(row,branchId,pathIndex,parentX,clientX){clearDropIndicators(row);const branch=findElement(branchId),path=branch?.paths[pathIndex];if(!path)return;const index=branchDropIndex(row,branchId,pathIndex,parentX,clientX),x=branchPathInsertX(path,index),line=row.closest('svg')?.querySelector(`[data-branch-insertion="${branchId}-${pathIndex}"]`),zone=row.closest('svg')?.querySelector(`[data-branch-drop="${branchId}"][data-path-index="${pathIndex}"]`);row.classList.add('drop-target');zone?.classList?.add('branch-path-over');row.dataset.dropIndex=String(index);line?.setAttribute('x1',x);line?.setAttribute('x2',x);line?.setAttribute('visibility','visible');}
function clearDropIndicators(except=null){root.querySelectorAll('.ladder-row.drop-target').forEach(row=>{if(row===except)return;row.classList.remove('drop-target');delete row.dataset.dropIndex;const line=row.querySelector('[data-insertion-indicator]')||row.closest('svg')?.querySelector(`[data-insertion-indicator="${row.dataset.rung}"]`);line?.setAttribute('visibility','hidden');line?.setAttribute('y1','35');line?.setAttribute('y2','145');});root.querySelectorAll('[data-branch-insertion]').forEach(line=>line.setAttribute('visibility','hidden'));root.querySelectorAll('[data-branch-drop]').forEach(zone=>zone.classList?.remove('branch-path-over'));}
function dropLibraryComponent(type,row,clientX,branchTarget=null){const rung=circuit.rungs.find(item=>item.id===row.dataset.rung);if(!rung||!type){setFeedback('That component cannot be dropped here.');return;}if(branchTarget){const branchId=branchTarget.dataset.branchDrop,pathIndex=Number(branchTarget.dataset.pathIndex),parentX=Number(branchTarget.dataset.branchX);if(!Number.isInteger(pathIndex)||!Number.isFinite(parentX)){setFeedback('Drop into one of the highlighted branch paths.');return;}addElement(type,rung.id,branchDropIndex(row,branchId,pathIndex,parentX,clientX),{branchId,pathIndex});return;}const index=rungDropIndex(row,clientX,false);addElement(type,rung.id,index);}

function playgroundView(){const visibleTags=circuit.monitorTags||[],tags=Object.entries(last.tags).filter(([tag])=>visibleTags.includes(tag)),tagManager=monitorManageOpen?`<fieldset class="monitor-tag-chooser"><legend>Visible tags</legend>${Object.entries(last.tags).map(([tag,value])=>`<label><input type="checkbox" data-monitor-tag="${escape(tag)}" ${visibleTags.includes(tag)?'checked':''}><span>${escape(tag)}</span><small>${typeof value==='boolean'?'BOOL':'NUMBER'}</small></label>`).join('')}</fieldset>`:'';const rungs=ladderWorkspace();const chosen=findElement(selectedComponentId);return `${heading('PLAYGROUND · LOCAL PROJECT','Motor starter','Build a rung, change tags, and follow a deterministic scan.',`<div class="project-actions"><button class="secondary-button" data-action="export">↓ Export</button><label class="secondary-button upload-button">↑ Import<input data-import type="file" accept="application/json"></label></div>`)}<div class="workspace-tools"><button class="secondary-button" data-action="components-panel" aria-controls="component-panel" aria-expanded="${componentsOpen}">${componentsOpen?'Hide':'Show'} components</button><button class="secondary-button" data-action="monitor-panel" aria-controls="monitor-panel" aria-expanded="${monitorOpen}">${monitorOpen?'Hide':'Show'} tag monitor</button><button class="secondary-button flow-toggle" data-action="flow-toggle" aria-pressed="${flowEnabled}">Flow animation: ${flowEnabled?'On':'Off'}</button><span>Drag placed instructions to reorder; branch paths move together.</span></div><div class="playground-layout${componentsOpen?' components-open':''}${monitorOpen?' monitor-open':''}">${componentsOpen?`<aside class="tool-panel" id="component-panel"><div class="panel-title">COMPONENTS</div><p class="panel-subtitle">Click to add a symbol, or drag it onto a rung.</p>${palette('CONTACTS',[['no','—| |—','NO contact'],['nc','—|/|—','NC contact'],['edge','↑','One-shot']])}${palette('COILS',[['coil','—( )—','Output'],['set','—(S)—','Set'],['unlatch','—(U)—','Unlatch']])}${palette('TIMERS',[['ton','TON','On-delay'],['tof','TOF','Off-delay'],['tp','TP','Pulse'],['rto','RTO','Retentive']])}${palette('COUNTERS & LOGIC',[['ctu','CTU','Count up'],['ctd','CTD','Count down'],['res','RES','Reset block'],['compare','≥','Compare'],['branch','⑂','OR branch']])}${palette('ARITHMETIC',[['add','+','Add'],['sub','−','Subtract'],['mul','×','Multiply'],['div','÷','Divide'],['move','MOV','Move']])}<button class="add-rung" data-action="add-rung">＋ Add rung</button><button class="add-rung" data-action="add-tag">＋ Add variable</button></aside>`:''}<section class="editor-column"><div class="editor-card"><div class="editor-toolbar"><div class="simulation-state"><span class="${running?'live-dot':'idle-dot'}"></span><b>${running?'RUNNING':'READY'}</b><small>Scan ${scanNumber}</small></div><div class="sim-controls"><button class="control-button" data-action="run" ${running?'disabled':''}>▶ Run</button><button class="control-button" data-action="pause" ${running?'':'disabled'}>Ⅱ Pause</button><button class="control-button" data-action="scan">▷ Single scan</button><button class="control-button" data-action="stop">■ Stop</button><button class="control-button subtle" data-action="reset">↻ Reset</button></div><label class="simulation-speed">Scan step<select data-simulation-speed aria-label="Simulation time advanced per scan">${[50,100,250,500].map(v=>`<option value="${v}" ${simulationStepMs===v?'selected':''}>${v} ms</option>`).join('')}</select></label></div><div class="editor-body"><div class="rung-heading"><span>ROUTINE: MAIN</span><span>${circuit.rungs.length} RUNGS</span></div>${rungs}</div><div class="editor-footer"><span><i class="legend-energized"></i> Energized path</span><span>SCAN MODEL <b data-scan-step>Deterministic · ${simulationStepMs} ms per scan</b></span></div></div>${chosen?propertyEditor(chosen):''}${selectedRungId? rungOptions():''}<details class="explanation-card"><summary><span class="explanation-icon">✳</span><span><span class="card-label">SCAN EXPLANATION</span><p data-scan-explanation>${last.trace.slice(-4).map(t=>escape(t.detail)).join(' · ')||'Run one scan to see each instruction update in order.'}</p></span></summary><button class="text-link" data-action="scan-info">How scans work</button></details><div class="feedback" data-feedback ${feedback?'':'hidden'}>${escape(feedback)}</div></section>${monitorOpen?`<aside class="monitor-panel" id="monitor-panel"><div class="monitor-heading"><div><h3>Live monitor</h3><small>TAG TABLE · ${tags.length} TAGS</small></div><div class="monitor-actions"><button data-action="monitor-tags" aria-expanded="${monitorManageOpen}">${monitorManageOpen?'Done':'Choose tags'}</button><button data-action="add-tag" aria-label="Add variable">＋</button></div></div>${tagManager}<div class="tag-list">${tags.map(renderTagRow).join('')}</div><div class="monitor-note"><b>Input vs output</b><p>Input tags are learner-controlled. OTE coils write their tag during each scan.</p></div><div class="history-title">RECENT SCAN EVENTS</div><div class="event-list">${history.slice(0,6).map(h=>`<div class="event-row"><span class="event-on"></span><span><b>Scan ${h.number}</b> ${h.changed.length?escape(h.changed.join(', ')):escape(h.trace.at(-1)?.detail||'No value changes')}</span></div>`).join('')}</div>${last.diagnostics.length?`<div class="diagnostics">${last.diagnostics.map(d=>`<p>⚠ ${escape(d)}</p>`).join('')}</div>`:''}</aside>`:''}</div>`;}
function rungOptions(){const i=circuit.rungs.findIndex(r=>r.id===selectedRungId);return `<section class="rung-options" aria-label="Selected rung options"><div><b>Rung ${String(i+1).padStart(2,'0')} selected</b><small>Drag its handle in the workspace to change order.</small></div><button class="rung-delete" data-action="delete-rung" ${circuit.rungs.length<=1?'disabled':''}>Delete rung</button></section>`;}
function renderTagRow([tag,value]){const input=circuit.inputTags?.includes(tag);if(input)value=circuit.tags[tag];const control=input&&typeof value==='number'?`<input class="tag-value" data-tag-state type="number" step="any" aria-label="Set ${escape(tag)}" data-number-tag="${escape(tag)}" value="${escape(value)}">`:input?`<button class="tag-value ${value?'on':''}" data-tag-state data-tag="${escape(tag)}"${isEdgeInput(tag)?` data-press-tag="${escape(tag)}"`:''}>${value?'ON':'OFF'}</button>`:`<span class="tag-value ${value?'on':''}" data-tag-state>${typeof value==='boolean'?(value?'ON':'OFF'):escape(value)}</span>`;return `<div class="tag-row" data-monitor-row="${escape(tag)}"><span class="tag-bulb ${value?'on':''}" data-tag-bulb></span><div class="tag-meta"><b>${escape(tag)}</b><small>${typeof value==='boolean'?'BOOL':'NUMBER'}${input?' · INPUT':''}</small></div>${control}</div>`;}
function palette(title,items){return `<div class="palette-group"><small>${title}</small><div class="palette-grid">${items.map(([type,symbol,name])=>`<button data-add="${type}"><b>${symbol}</b><span>${name}</span></button>`).join('')}</div></div>`;}
function findElement(elementId){if(!elementId)return null;for(const r of circuit.rungs){const found=findIn(r.elements,elementId);if(found)return found;}return null;}
function isEdgeInput(tag){return circuit.rungs.some(r=>nestedInstructions(r.elements).some(e=>e.type==='edge'&&e.tag===tag));}
function findIn(items,id){for(const e of items){if(e.id===id)return e;if(e.type==='branch')for(const p of e.paths){const f=findIn(p,id);if(f)return f;}}return null;}
function componentFacts(e){if(e.type==='contact'&&e.mode==='no')return{name:'Normally Open Contact',purpose:'Checks whether the assigned Boolean tag is TRUE.',use:'Commonly used for push buttons, sensor signals, and permissive conditions.',behavior:'Conducts when the tag is TRUE; otherwise it interrupts the rung path.'};if(e.type==='contact')return{name:'Normally Closed Contact',purpose:'Checks whether the assigned Boolean tag is FALSE.',use:'Commonly used for stop conditions and interlocks, depending on circuit design.',behavior:'Conducts while its tag is FALSE and blocks when its tag is TRUE.'};if(e.type==='coil'&&e.mode==='ote')return{name:'Output Coil (OTE)',purpose:'Writes the evaluated rung result to its assigned output tag.',use:'Commonly drives a logical output such as a motor command or indicator.',behavior:'Writes TRUE when the rung is true and FALSE when it is false on each scan.'};if(e.type==='coil')return{name:e.mode==='otl'?'Set Coil (OTL)':'Reset Coil (OTU)',purpose:'Stores an output state when its rung becomes true.',use:'Used for retained states that need a separate set and reset condition.',behavior:e.mode==='otl'?'Sets its tag TRUE when the rung is true; otherwise it retains its value.':'Sets its tag FALSE when the rung is true; otherwise it retains its value.'};const facts={edge:{name:'Edge Detector',purpose:'Detects a rising or falling transition in rung power.',use:'Used when an event should happen once per transition.',behavior:'Emits a one-scan pulse for the configured edge.'},branch:{name:'Parallel Branch',purpose:'Creates alternate logic routes within a rung.',use:'Used to express OR conditions or holding paths.',behavior:'The branch conducts when any path conducts.'},timer:{name:`${(e.mode||'ton').toUpperCase()} Timer`,purpose:'Tracks time while its rung enable is active.',use:'Used for delays, pulse durations, or accumulated runtime.',behavior:'Its enable and preset govern its elapsed time and status bits.'},counter:{name:`${(e.mode||'ctu').toUpperCase()} Counter`,purpose:'Counts configured rung transitions and compares the count with a preset.',use:'Used to track parts, cycles, or discrete events.',behavior:'Its accumulator and done state update according to the selected count mode.'},reset:{name:'Reset Instruction (RES)',purpose:'Clears the accumulated state of its target timer or counter.',use:'Used to return a timer or counter to its initial accumulated value.',behavior:'Clears the matching instruction state when its rung is true.'},compare:{name:'Comparison Instruction',purpose:'Compares two numeric values and returns a Boolean result.',use:'Used for thresholds, ranges, and numeric permissives.',behavior:'The configured operator determines whether rung power continues.'},math:{name:`${(e.op||'math').toUpperCase()} Instruction`,purpose:'Calculates or copies a numeric value when enabled.',use:'Used to update a numeric destination from operands.',behavior:'Writes the destination value when the instruction is enabled.'}};return facts[e.type]||{name:e.type.toUpperCase(),purpose:'Evaluates as part of the current rung.',use:'Used to build a control condition.',behavior:'Follows the simulator behavior for this instruction.'};}
function propertyEditor(e){let field='';if(e.type==='contact')field=`<label>Contact type<select data-prop="mode"><option value="no" ${e.mode==='no'?'selected':''}>Normally open</option><option value="nc" ${e.mode==='nc'?'selected':''}>Normally closed</option></select></label><label>Variable tag<select data-prop="tag">${Object.entries(last.tags).filter(([,value])=>typeof value==='boolean').map(([name])=>`<option value="${escape(name)}" ${e.tag===name?'selected':''}>${escape(name)}</option>`).join('')}</select></label>`;else if(e.type==='coil')field=`<label>Coil type<select data-prop="mode"><option value="ote" ${e.mode==='ote'?'selected':''}>Output</option><option value="otl" ${e.mode==='otl'?'selected':''}>Set</option><option value="otu" ${e.mode==='otu'?'selected':''}>Reset</option></select></label><label>Variable tag<input data-prop="tag" value="${escape(e.tag)}"></label>`;else if(e.type==='edge')field=`<label>Edge<select data-prop="mode"><option value="rising" ${e.mode==='rising'?'selected':''}>Rising</option><option value="falling" ${e.mode==='falling'?'selected':''}>Falling</option></select></label><label>Variable tag<select data-prop="tag">${Object.entries(last.tags).filter(([,value])=>typeof value==='boolean').map(([name])=>`<option value="${escape(name)}" ${e.tag===name?'selected':''}>${escape(name)}</option>`).join('')}</select></label>`;else if(e.type==='timer')field=`<label>Timer type<select data-prop="mode">${['ton','tof','tp','rto'].map(v=>`<option value="${v}" ${e.mode===v?'selected':''}>${v.toUpperCase()}</option>`).join('')}</select></label><label>Timer tag<input data-prop="tag" value="${escape(e.tag)}"></label><label>Preset (ms)<input type="number" min="0" data-prop="presetMs" value="${e.presetMs}"></label>`;else if(e.type==='counter')field=`<label>Counter type<select data-prop="mode"><option value="ctu" ${e.mode==='ctu'?'selected':''}>Count up</option><option value="ctd" ${e.mode==='ctd'?'selected':''}>Count down</option></select></label><label>Counter tag<input data-prop="tag" value="${escape(e.tag)}"></label><label>Preset<input type="number" data-prop="preset" value="${e.preset}"></label>`;else if(e.type==='reset')field=`<label>Target tag<input data-prop="target" value="${escape(e.target)}"></label>`;else if(e.type==='compare')field=`<label>Operator<select data-prop="op">${['gt','lt','gte','lte','eq','neq'].map(v=>`<option value="${v}" ${e.op===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Left tag<input data-prop="left" value="${escape(e.left)}"></label><label>Right operand<input data-prop="right" value="${escape(e.right)}"></label><label>Result tag<input data-prop="dest" value="${escape(e.dest||'')}"></label>`;else if(e.type==='math')field=`<label>Operation<select data-prop="op">${['add','sub','mul','div','move'].map(v=>`<option value="${v}" ${e.op===v?'selected':''}>${v.toUpperCase()}</option>`).join('')}</select></label><label>Left tag<input data-prop="left" value="${escape(e.left)}"></label><label>Right value<input data-prop="right" value="${escape(e.right)}"></label><label>Destination<input data-prop="dest" value="${escape(e.dest)}"></label>`;else if(e.type==='branch')field='<span>Drop instructions into either path to build the parallel condition.</span>';const facts=componentFacts(e),tag=e.tag||e.dest||e.target;return `<aside class="component-inspector" aria-label="${escape(facts.name)} information"><header><div><small>COMPONENT DETAILS · ${escape(e.type.toUpperCase())}${e.mode?` · ${escape(e.mode.toUpperCase())}`:''}</small><h3>${escape(facts.name)}</h3></div><button class="inspector-close" data-action="clear-selection" aria-label="Close component details">×</button></header><p>${escape(facts.purpose)}</p><dl><div><dt>Common use</dt><dd>${escape(facts.use)}</dd></div><div><dt>Behavior</dt><dd>${escape(facts.behavior)}</dd></div>${tag?`<div><dt>Assigned tag</dt><dd><code>${escape(tag)}</code></dd></div>`:''}</dl><details class="inspector-config"><summary>Configuration and properties</summary><div class="inspector-fields">${field||'<span>No editable properties.</span>'}</div></details><button class="delete-component" data-action="delete-selected">Delete component</button></aside>`;}

function componentsView(){const rows=components.filter(c=>`${c.name} ${c.symbol} ${c.group} ${c.purpose}`.toLowerCase().includes(search.toLowerCase()));return `${heading('REFERENCE · FIELD GUIDE','Component library','Understand each instruction before you place it in a circuit.') }<div class="library-search"><span>⌕</span><input aria-label="Search components" placeholder="Search by name, symbol or behavior…" value="${escape(search)}"><span class="shortcut">/</span></div><div class="component-grid">${rows.map(c=>`<article class="component-card"><div class="component-top"><span class="component-symbol">${escape(c.symbol)}</span><span class="group-pill">${c.group}</span></div><h3>${escape(c.name)}</h3><p>${escape(c.purpose)}</p><div class="component-detail"><small>CONFIGURATION</small><span>${escape(c.config)}</span></div><div class="component-example"><b>EXAMPLE</b><span>${escape(c.example)}</span></div><div class="component-mistake"><b>COMMON MISTAKE</b><span>${escape(c.mistake)}</span></div><button class="text-link" data-related="${escape(c.lesson)}">Related lesson: ${escape(c.lesson)} ↗</button></article>`).join('')}</div>`;}
function challengesView(){return `${heading('CHALLENGES · PRACTICE BY DOING','Put your logic to work','Build behavior that holds across test cases. Hints reveal one idea at a time.',`<span class="challenge-progress">${Number(localStorage.getItem('lltl-challenges-done')||0)} / ${challenges.length} COMPLETED</span>`)}<div class="challenge-list">${challenges.map((c,i)=>`<article class="challenge-card"><div class="challenge-number">${String(i+1).padStart(2,'0')}</div><div class="challenge-content"><div class="challenge-tags"><span>${c.level}</span><span>${c.time}</span></div><h2>${escape(c.title)}</h2><p>${escape(c.description)}</p><div class="requirements"><b>REQUIREMENTS</b>${c.requirements.map(r=>`<span>✓ ${escape(r)}</span>`).join('')}</div><div class="challenge-actions"><button class="primary-button" data-open-challenge="${i}">Open challenge <span>→</span></button><button class="hint-button" data-hint="${i}">◈ Reveal hint ${Math.min((Number(localStorage.getItem(`lltl-hints-${i}`)||0)+1),c.hints.length)}</button><button class="quiet-button" data-test-challenge="${i}">Test circuit</button></div></div><div class="challenge-status">${localStorage.getItem(`lltl-challenge-${i}`)==='done'?'COMPLETED':'NOT STARTED'}</div></article>`).join('')}</div><div class="feedback" data-feedback ${feedback?'':'hidden'}>${escape(feedback)}</div>`;}

function render(){save();const content=activeTab==='Learn'?learnView():activeTab==='Playground'?playgroundView():activeTab==='Components'?componentsView():challengesView();const pageClass=activeTab==='Playground'?'page-content page-playground':'page-content page-scroll';root.innerHTML=`<div class="app-shell ${running?'simulation-running':''} ${flowEnabled?'':'flow-disabled'}">${header()}<main class="main-area"><div class="${pageClass}">${content}</div></main></div>`;bind();}
function updateSimulationView(){const shell=el('.app-shell');if(shell){shell.classList.toggle('simulation-running',running);shell.classList.toggle('flow-disabled',!flowEnabled);shell.style.setProperty('--flow-duration',`${Math.min(1500,Math.max(350,simulationStepMs*2))}ms`);}for(const wire of root.querySelectorAll('[data-wire-key]')){const active=wireSegmentEnergized(last.trace,wire.dataset.wireRung,wire.dataset.wireTrace,wire.dataset.wirePhase);wire.classList.toggle('active',active);}for(const symbol of root.querySelectorAll('[data-sim-symbol]')){const state=traceFor(symbol.dataset.rungId,symbol.dataset.traceId||symbol.dataset.elementId),coil=symbol.dataset.elementType==='coil',visual=componentVisualState(last.trace,last.tags,symbol.dataset.rungId,symbol.dataset.elementId,symbol.dataset.elementType,symbol.dataset.outputTag||'',symbol.dataset.traceId||symbol.dataset.elementId),active=visual.energized;symbol.classList.toggle('symbol-active',active);symbol.classList.toggle('condition-true',state?.condition===true);symbol.classList.toggle('condition-false',state?.condition===false);if(symbol.dataset.elementType==='timer')for(const phase of ['idle','enabled','timing','done'])symbol.classList.toggle(`timer-${phase}`,phase===(state?.timerPhase||'IDLE').toLowerCase());if(symbol.dataset.elementType==='compare'){symbol.classList.toggle('compare-true',Boolean(state?.result));symbol.classList.toggle('compare-false',!state?.result);}const title=symbol.querySelector('[data-trace-detail]');if(title)title.textContent=state?.detail||'Not evaluated';const detail=symbol.querySelector('[data-live-detail]');if(detail&&symbol.dataset.elementType==='timer'){const element=findElement(symbol.dataset.elementId);detail.textContent=`${((state?.elapsedMs||0)/1000).toFixed(1)} / ${((state?.presetMs||element?.presetMs||0)/1000).toFixed(1)} s · ${state?.timerPhase||'IDLE'}`;}else if(detail&&symbol.dataset.elementType==='compare')detail.textContent=state?.summary||'NOT EVALUATED';else if(detail&&coil)detail.textContent=state?.outputValue?'ON':'OFF';else if(detail&&symbol.dataset.elementType==='counter')detail.textContent=`${state?.accumulator||0} / ${state?.preset||0}`;}const scanLabel=el('.simulation-state small');if(scanLabel)scanLabel.textContent=`Scan ${scanNumber}`;const stepLabel=el('[data-scan-step]');if(stepLabel)stepLabel.textContent=`Deterministic · ${simulationStepMs} ms per scan`;const stateLabel=el('.simulation-state b');if(stateLabel)stateLabel.textContent=running?'RUNNING':'READY';const lamp=el('.simulation-state .live-dot, .simulation-state .idle-dot');if(lamp){lamp.classList.toggle('live-dot',running);lamp.classList.toggle('idle-dot',!running);}for(const row of root.querySelectorAll('[data-monitor-row]')){const tag=row.dataset.monitorRow,value=circuit.inputTags?.includes(tag)?circuit.tags[tag]:last.tags[tag],bulb=row.querySelector('[data-tag-bulb]'),display=row.querySelector('[data-tag-state]');if(bulb)bulb.classList.toggle('on',Boolean(value));if(display){display.classList.toggle('on',Boolean(value));if(display.tagName==='INPUT')display.value=String(value??'');else display.textContent=typeof value==='boolean'?(value?'ON':'OFF'):String(value??'');}}const expl=el('[data-scan-explanation]');if(expl)expl.textContent=last.trace.slice(-4).map(item=>item.detail).join(' · ')||'Run one scan to see each instruction update in order.';const events=el('.event-list');if(events)events.innerHTML=history.slice(0,6).map(item=>`<div class="event-row"><span class="event-on"></span><span><b>Scan ${item.number}</b> ${item.changed.length?escape(item.changed.join(', ')):escape(item.trace.at(-1)?.detail||'No value changes')}</span></div>`).join('');}
function bind(){root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{activeTab=b.dataset.tab;if(activeTab!=='Playground')running=false;selectedComponentId=null;selectedRungId=null;feedback='';render();});root.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{lessonIndex=Number(b.dataset.lesson);quizChoice='';feedback='';render();});root.querySelectorAll('[data-tag]').forEach(b=>b.onclick=()=>{const tag=b.dataset.tag;if(isEdgeInput(tag))return;const v=circuit.tags[tag];setTag(tag,typeof v==='boolean'?!v:Number(v)+1);});root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{if(!b.closest('.editor-column')){selectedComponentId=null;selectedRungId=null;}action(b.dataset.action);});root.querySelectorAll('[data-monitor-tag]').forEach(input=>input.onchange=()=>{circuit.monitorTags??=[];const tag=input.dataset.monitorTag;if(input.checked&&!circuit.monitorTags.includes(tag))circuit.monitorTags.push(tag);else if(!input.checked)circuit.monitorTags=circuit.monitorTags.filter(item=>item!==tag);save();render();});const speed=el('[data-simulation-speed]');if(speed)speed.onchange=()=>{simulationStepMs=Number(speed.value);localStorage.setItem('lltl-scan-step',String(simulationStepMs));updateSimulationView();};root.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>addElement(b.dataset.add));root.querySelectorAll('[data-related]').forEach(b=>b.onclick=()=>{lessonIndex=lessons.findIndex(l=>l.title===b.dataset.related);quizChoice='';activeTab='Learn';running=false;render();});root.querySelectorAll('[data-hint]').forEach(b=>b.onclick=()=>revealHint(Number(b.dataset.hint)));root.querySelectorAll('[data-test-challenge]').forEach(b=>b.onclick=()=>testChallenge(Number(b.dataset.testChallenge)));root.querySelectorAll('[data-open-challenge]').forEach(b=>b.onclick=()=>{challengeIndex=Number(b.dataset.openChallenge);activeTab='Playground';feedback=`Challenge loaded: ${challenges[challengeIndex].title}. Build and test the required behavior.`;render();});const searchBox=el('.library-search input');if(searchBox)searchBox.oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;const y=window.scrollY;render();const next=el('.library-search input');next.focus();next.setSelectionRange(pos,pos);window.scrollTo(0,y);};const importer=el('[data-import]');if(importer)importer.onchange=()=>importFile(importer.files[0]);root.querySelectorAll('[data-number-tag]').forEach(input=>input.onchange=()=>{const value=Number(input.value);if(Number.isFinite(value))setTag(input.dataset.numberTag,value);});root.querySelectorAll('[data-prop]').forEach(input=>input.onchange=()=>updateProp(input.dataset.prop,input.value));root.querySelectorAll('[data-add]').forEach(button=>{button.draggable=true;button.ondragstart=event=>{paletteDrag=button.dataset.add;event.dataTransfer.effectAllowed='copy';event.dataTransfer.setData('application/x-lltl-component',paletteDrag);};button.ondragend=()=>{if(paletteDrag){paletteDrag=null;clearDropIndicators();setFeedback('Drop a component onto a rung to add it to the circuit.');}};});root.querySelectorAll('.ladder-row').forEach(row=>{row.ondragover=event=>{if(!Array.from(event.dataTransfer.types||[]).includes('application/x-lltl-component'))return;event.preventDefault();event.dataTransfer.dropEffect='copy';const target=event.target?.closest?.('[data-branch-drop]');if(target)showBranchDropIndicator(row,target.dataset.branchDrop,Number(target.dataset.pathIndex),Number(target.dataset.branchX),event.clientX);else showDropIndicator(row,event.clientX);};row.ondragleave=event=>{if(!row.contains(event.relatedTarget))clearDropIndicators();};row.ondrop=event=>{if(!Array.from(event.dataTransfer.types||[]).includes('application/x-lltl-component'))return;event.preventDefault();const type=event.dataTransfer.getData('application/x-lltl-component'),target=event.target?.closest?.('[data-branch-drop]');paletteDrag=null;clearDropIndicators();dropLibraryComponent(type,row,event.clientX,target);};});}
function action(name){if(name==='theme'){theme=theme==='dark'?'light':'dark';localStorage.setItem('lltl-theme',theme);document.documentElement.dataset.theme=theme;render();}else if(name==='run')startRun();else if(name==='pause'){running=false;render();}else if(name==='stop'){running=false;render();}else if(name==='reset')reset();else if(name==='scan')scanOnce();else if(name==='components-panel'){componentsOpen=!componentsOpen;render();}else if(name==='monitor-panel'){monitorOpen=!monitorOpen;render();}else if(name==='monitor-tags'){monitorManageOpen=!monitorManageOpen;render();}else if(name==='flow-toggle'){flowEnabled=!flowEnabled;localStorage.setItem('lltl-flow-animation',flowEnabled?'on':'off');render();}else if(name==='add-rung')addRung();else if(name==='delete-rung')deleteSelectedRung();else if(name==='add-tag')addTag();else if(name==='delete-selected')deleteSelected();else if(name==='clear-selection'){selectedComponentId=null;render();}else if(name==='open-play'){activeTab='Playground';feedback='Toggle Start, then advance a scan to trace the rung.';render();}else if(name==='lesson-check'){if(quizChoice===''){setFeedback('Choose an answer before checking.');return;}const quiz=lessonQuizzes[lessonIndex];if(Number(quizChoice)===quiz[2]){localStorage.setItem(`lltl-lesson-${lessonIndex}`,'done');setFeedback('Correct. Explain how the example demonstrates this idea, then continue when ready.');}else setFeedback('Not quite. Revisit the key idea and trace the example once more.');}else if(name==='prev'){lessonIndex=Math.max(0,lessonIndex-1);quizChoice='';render();}else if(name==='next'){lessonIndex=Math.min(lessons.length-1,lessonIndex+1);quizChoice='';render();}else if(name==='export')exportProject();else if(name==='scan-info')setFeedback('This lab snapshots inputs at scan start, evaluates rungs from top to bottom, and makes timer and coil writes available to later rungs during the same scan. Comparison blocks write their result tag for downstream contacts.');else if(name==='help')setFeedback('Ladder Logic Tutor Lab runs entirely in this browser. Use Playground to edit and simulate; data stays on this device.');}
function uniqueInstructionTag(prefix){const used=new Set(Object.keys(circuit.tags));const visit=items=>{for(const item of items){if(item.tag)used.add(item.tag);if(item.dest)used.add(item.dest);if(item.type==='branch')for(const path of item.paths)visit(path);}};for(const rung of circuit.rungs)visit(rung.elements);let n=1;while(used.has(`${prefix}_${n}`))n++;return `${prefix}_${n}`;}
function addElement(type,rungId,index=null,targetPath=null){
 const boolTags=Object.keys(circuit.tags).filter(tag=>typeof circuit.tags[tag]==='boolean');
 const inputTag=(circuit.inputTags||[]).find(tag=>boolTags.includes(tag))||boolTags[0]||'Start';
 const tag=boolTags.find(name=>name!=='Motor'&&name!=='Lamp')||inputTag;let e;
 if(type==='no'||type==='nc')e={id:id(type),type:'contact',mode:type,tag};
 else if(type==='coil')e={id:id('ote'),type:'coil',mode:'ote',tag:'Lamp'};
 else if(type==='set'||type==='unlatch')e={id:id(type),type:'coil',mode:type==='set'?'otl':'otu',tag:'Lamp'};
 else if(type==='edge')e={id:id('edge'),type:'edge',mode:'rising',tag:inputTag};
 else if(['ton','tof','tp','rto'].includes(type))e={id:id(type),type:'timer',mode:type,tag:uniqueInstructionTag(type.toUpperCase()),presetMs:2000};
 else if(type==='ctu'||type==='ctd')e={id:id(type),type:'counter',mode:type,tag:uniqueInstructionTag(type.toUpperCase()),preset:3};
 else if(type==='res')e={id:id('res'),type:'reset',target:'CTU_1'};
 else if(type==='compare'){const timers=circuit.rungs.flatMap(rung=>rung.elements).filter(item=>item.type==='timer'),timer=timers.at(-1);e={id:id('compare'),type:'compare',op:'gte',left:timer?`${timer.tag}.ET`:'Count',right:timer?timer.presetMs:3,dest:uniqueInstructionTag('Compare')};}
 else if(['add','sub','mul','div','move'].includes(type))e={id:id(type),type:'math',op:type,left:'Count',right:1,dest:'Count'};
 else if(type==='branch')e={id:id('branch'),type:'branch',paths:[[],[]]};
 else e={id:id('branch'),type:'branch',paths:[[],[]]};
 const rung=circuit.rungs.find(item=>item.id===rungId)||circuit.rungs.at(-1);if(!rung)return;
 let at=index===null?(rung.elements.at(-1)?.type==='coil'?rung.elements.length-1:rung.elements.length):Math.max(0,Math.min(rung.elements.length,Math.trunc(index)));
 if(rung.elements.at(-1)?.type==='coil'&&!targetPath)at=Math.min(at,rung.elements.length-1);
 const inserted=targetPath?insertBranchElement(circuit,rung.id,targetPath.branchId,targetPath.pathIndex,e,index??0):insertRungElement(circuit,rung.id,e,at);
 if(!inserted){setFeedback('That component could not be inserted at this drop position.');return;}
 if(e.type==='coil')circuit.inputTags=(circuit.inputTags||[]).filter(name=>name!==e.tag);
 selectedComponentId=e.type==='branch'?null:e.id;selectedRungId=null;save();last=scan(circuit,memory);memory=last.memory;
 feedback=e.type==='branch'?'Empty parallel branch added. Drop instructions into either path.':`${e.type.toUpperCase()} added. Select its symbol to edit properties.`;render();
}
function selectRung(rungId){if(!circuit.rungs.some(r=>r.id===rungId))return;selectedComponentId=null;selectedRungId=rungId;render();}
function addRung(){const rung={id:id('rung'),elements:[]};circuit.rungs.push(rung);selectedComponentId=null;selectedRungId=null;save();render();}
function nestedInstructions(elements){return(elements||[]).flatMap(e=>e.type==='branch'?[e,...e.paths.flatMap(nestedInstructions)]:[e]);}
function clearDeletedInstructionState(removed){const still=nestedInstructions(circuit.rungs.flatMap(r=>r.elements));for(const e of nestedInstructions(removed)){if(e.type==='coil'&&!still.some(other=>other.type==='coil'&&other.tag===e.tag)&&!(circuit.inputTags||[]).includes(e.tag)){circuit.tags[e.tag]=false;memory.values[e.tag]=false;}if(e.type==='timer'&&!still.some(other=>other.type==='timer'&&other.tag===e.tag)){delete memory.timers[e.id];for(const suffix of ['EN','TT','Q','ACC','ET','PRE'])delete memory.values[`${e.tag}.${suffix}`];}if(e.type==='counter'&&!still.some(other=>other.type==='counter'&&other.tag===e.tag)){delete memory.counters[e.id];for(const suffix of ['Q','ACC','PRE'])delete memory.values[`${e.tag}.${suffix}`];}if(e.type==='edge')delete memory.edges[e.id];if((e.type==='compare'||e.type==='math')&&e.dest&&!still.some(other=>['compare','math'].includes(other.type)&&other.dest===e.dest)){delete memory.values[e.dest];circuit.tags[e.dest]=e.type==='math'?0:false;}}}
function deleteSelectedRung(){const index=circuit.rungs.findIndex(r=>r.id===selectedRungId);if(index<0)return;if(circuit.rungs.length<=1){feedback='Keep at least one rung in the routine.';render();return;}const rung=circuit.rungs[index];if(!confirm(`Delete rung ${index+1} and its instructions? Referenced tags will be kept.`))return;const deleted=deleteRung(circuit,selectedRungId);if(!deleted)return;clearDeletedInstructionState(deleted.elements);selectedComponentId=null;selectedRungId=null;last=scan(circuit,memory,0);memory=last.memory;save();feedback='Rung deleted. Its tags were kept.';render();}
function addBranchContact(branchId,pathIndex){const branch=findElement(branchId);if(!branch||branch.type!=='branch'||!branch.paths[pathIndex])return;const tag=(circuit.inputTags||[]).find(t=>typeof circuit.tags[t]==='boolean')||Object.keys(circuit.tags).find(name=>typeof circuit.tags[name]==='boolean')||'Start';branch.paths[pathIndex].push({id:id('contact'),type:'contact',mode:'no',tag});save();last=scan(circuit,memory,0);memory=last.memory;render();}
function addTag(){const name=prompt('New variable name (letters, numbers and underscores):','NewInput');if(!name)return;const valid=name.trim().replace(/\s+/g,'_');if(!/^[A-Za-z_][\w.]*$/.test(valid)){setFeedback('Use a valid tag name beginning with a letter or underscore.');return;}if(valid in circuit.tags){setFeedback('That tag already exists.');return;}const type=(prompt('Enter BOOL for a Boolean input or NUMBER for a numeric input:','BOOL')||'BOOL').toUpperCase();circuit.tags[valid]=type==='NUMBER'?0:false;circuit.inputTags??=[];circuit.inputTags.push(valid);save();render();setFeedback(`${valid} ${type==='NUMBER'?'numeric':'Boolean'} input tag created.`);}
function updateProp(prop,value){const e=findElement(selectedComponentId);if(!e)return;if(prop==='presetMs'||prop==='preset')e[prop]=Math.max(0,Number(value)||0);else if(prop==='right'&&/^-?\d+(\.\d+)?$/.test(value))e[prop]=Number(value);else e[prop]=value;if(prop==='tag'&&e.type==='coil')circuit.inputTags=(circuit.inputTags||[]).filter(t=>t!==value);save();last=scan(circuit,memory,0);memory=last.memory;render();}
function deleteSelected(){if(!selectedComponentId)return;const element=findElement(selectedComponentId);if(!element)return;const facts=componentFacts(element);if(!confirm(`Delete ${facts.name}${element.tag?` (${element.tag})`:''}?`))return;const removed=[element],drop=items=>items.filter(e=>e.id!==selectedComponentId).map(e=>e.type==='branch'?{...e,paths:e.paths.map(drop)}:e);circuit.rungs=circuit.rungs.map(r=>({...r,elements:drop(r.elements)}));clearDeletedInstructionState(removed);selectedComponentId=null;save();last=scan(circuit,memory,0);memory=last.memory;feedback=`${facts.name} deleted.`;render();}
function testChallenge(index){const c=challenges[index],trial=clone(circuit),inputs=trial.inputTags||Object.keys(trial.tags).filter(k=>typeof trial.tags[k]==='boolean');let ok=false,mem=emptyMemory(),r;
 const all=items=>items.flatMap(e=>e.type==='branch'?[e,...e.paths.flatMap(all)]:[e]);const instructions=trial.rungs.flatMap(rung=>all(rung.elements));
 for(const tag of inputs)trial.tags[tag]=typeof trial.tags[tag]==='number'?0:false;
 for(const item of instructions)if(item.type==='contact'&&inputs.includes(item.tag))trial.tags[item.tag]=item.mode==='no';
 const scanNow=(dt=0)=>{r=scan(trial,mem,dt);mem=r.memory;return r;};
 if(index===0){const input=instructions.find(e=>e.type==='contact'&&e.mode==='no')?.tag;const output=instructions.find(e=>e.type==='coil'&&e.mode==='ote'&&/lamp/i.test(e.tag))?.tag;if(input&&output){trial.tags[input]=true;const on=scanNow().tags[output];trial.tags[input]=false;const off=scanNow().tags[output];ok=on===true&&off===false;}}
 if(index===1){const no=instructions.find(e=>e.type==='contact'&&e.mode==='no')?.tag,nc=instructions.find(e=>e.type==='contact'&&e.mode==='nc')?.tag,out=instructions.find(e=>e.type==='coil'&&e.mode==='ote')?.tag;if(no&&nc&&out){trial.tags[no]=true;trial.tags[nc]=false;const allowed=scanNow().tags[out]===true;trial.tags[no]=false;const missingEnable=scanNow().tags[out]===false;trial.tags[no]=true;trial.tags[nc]=true;const stopped=scanNow().tags[out]===false;ok=allowed&&missingEnable&&stopped;}}
 if(index===2){const start=Object.keys(trial.tags).find(t=>/start/i.test(t)),stop=Object.keys(trial.tags).find(t=>/stop/i.test(t)),motor=Object.keys(trial.tags).find(t=>/motor/i.test(t));if(start&&stop&&motor){trial.tags[start]=true;trial.tags[stop]=false;scanNow();trial.tags[start]=false;const held=scanNow().tags[motor]===true;trial.tags[stop]=true;const stopped=scanNow().tags[motor]===false;ok=held&&stopped;}}
 if(index===3){const counter=instructions.find(e=>e.type==='counter'&&e.mode==='ctu'),res=instructions.find(e=>e.type==='reset'&&e.target===counter?.tag),coilOut=instructions.find(e=>e.type==='coil')?.tag;if(counter){const countTag=instructions.slice(0,instructions.indexOf(counter)).reverse().find(e=>e.type==='contact')?.tag;if(countTag){trial.tags[countTag]=false;scanNow();for(let n=0;n<counter.preset;n++){trial.tags[countTag]=true;scanNow();if(n<counter.preset-1){trial.tags[countTag]=false;scanNow();}}const counted=r.tags[`${counter.tag}.ACC`]===counter.preset&&r.tags[`${counter.tag}.Q`]===true;const held=scanNow().tags[`${counter.tag}.ACC`]===counter.preset;let resetOk=false;if(res){for(const input of inputs)if(typeof trial.tags[input]==='boolean')trial.tags[input]=true;resetOk=scanNow().tags[`${counter.tag}.ACC`]===0;}ok=counted&&held&&Boolean(res)&&resetOk&&Boolean(coilOut||counter.tag);}}}
 if(index===4){const timer=instructions.find(e=>e.type==='timer'&&e.mode==='ton'),qContact=instructions.some(e=>e.type==='contact'&&e.tag===`${timer?.tag}.Q`),out=instructions.find(e=>e.type==='coil')?.tag;if(timer&&qContact&&out){for(const item of instructions)if(item.type==='contact'&&inputs.includes(item.tag))trial.tags[item.tag]=item.mode==='no';const on=scanNow(timer.presetMs);const delayed=Boolean(on.tags[`${timer.tag}.Q`])&&Boolean(on.tags[out]);for(const tag of inputs)if(typeof trial.tags[tag]==='boolean')trial.tags[tag]=false;const off=scanNow(100);ok=delayed&&!off.tags[out];}}
 if(index===5){const level=inputs.find(t=>/^level$/i.test(t)),high=inputs.find(t=>/^high$/i.test(t)),highHigh=inputs.find(t=>/^high.?high$/i.test(t)),pump1=Object.keys(trial.tags).find(t=>/^pump.?1$/i.test(t)),pump2=Object.keys(trial.tags).find(t=>/^pump.?2$/i.test(t));if(level&&high&&highHigh&&pump1&&pump2){const h=Number(trial.tags[high]),hh=Number(trial.tags[highHigh]);for(const item of instructions)if(item.type==='contact'&&inputs.includes(item.tag))trial.tags[item.tag]=item.mode==='no';let casesPass=Number.isFinite(h)&&Number.isFinite(hh)&&h<hh;for(const [value,want1,want2] of [[h-1,true,false],[h,false,true],[hh,false,false],[hh+1,false,false]]){trial.tags[level]=value;const state=scanNow();casesPass=casesPass&&Boolean(state.tags[pump1])===want1&&Boolean(state.tags[pump2])===want2;}ok=casesPass;}}
 if(ok){localStorage.setItem(`lltl-challenge-${index}`,'done');localStorage.setItem('lltl-challenges-done',String(challenges.filter((_,i)=>localStorage.getItem(`lltl-challenge-${i}`)==='done').length));setFeedback(`Behavior tests passed for “${c.title}”.`);}else setFeedback(`Not yet. ${c.hint}`);render();}
function contains(items,pred){return items.some(e=>pred(e)||(e.type==='branch'&&e.paths.some(p=>contains(p,pred))));}
function revealHint(index){const challenge=challenges[index],level=Number(localStorage.getItem(`lltl-hints-${index}`)||0);if(level>=challenge.hints.length){feedback='You have seen all available hints. Try a new test sequence or review the component reference.';}else{localStorage.setItem(`lltl-hints-${index}`,String(level+1));feedback=`Hint ${level+1}: ${challenge.hints[level]}`;}render();}
function exportProject(){const blob=new Blob([JSON.stringify(circuit,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ladder-lab-project.json';a.click();URL.revokeObjectURL(a.href);}
function importFile(file){if(!file)return;file.text().then(text=>{try{const value=JSON.parse(text);if(!value.tags||!Array.isArray(value.rungs))throw Error();circuit=value;memory=emptyMemory();selectedComponentId=null;last=scan(circuit);render();setFeedback('Project loaded.');}catch{setFeedback('That file is not a valid Ladder Lab project.');}});}
render();
